<template><details class="site-operations" @toggle="opened"><summary>{{ $t(titles[scope]) }}</summary><div v-if="form">
<div class="settings-toolbar"><label>{{ $t('Editing language') }} <themed-select v-model="locale"><option value="zh-cn">简体中文</option><option value="zh-tw">繁體中文</option><option value="en">English</option></themed-select></label><button type="button" @click="usePublished">{{ $t('Load published version') }}</button><span>{{ $t(hasDraft?'Unpublished draft':'Published version') }}</span></div>
<template v-if="scope==='navigation'"><label><input type="checkbox" v-model="form.api_public"> {{ $t('Show public API documentation links') }}</label><p>{{ $t('This setting controls public navigation only. API services and key revocation remain available.') }}</p><article v-for="(g,i) in form.groups" :key="i" class="editor-box"><label>{{ $t('Group title') }}<input v-model="g.title[locale]" maxlength="50"></label><div class="moves"><button type="button" @click="move(form.groups,i,-1)" :disabled="!i">↑</button><button type="button" @click="move(form.groups,i,1)" :disabled="i===form.groups.length-1">↓</button><button type="button" @click="form.groups.splice(i,1)" :disabled="form.groups.length===1">{{ $t('Remove') }}</button></div><div v-for="(l,j) in g.links" :key="j" class="link-row"><input type="checkbox" v-model="l.visible" :aria-label="$t('Visible')"><input v-model="l.label[locale]" :aria-label="$t('Label')" maxlength="70"><themed-select v-model="l.path" :aria-label="$t('Destination')"><option v-for="p in targets" :key="p">{{ p }}</option></themed-select><button type="button" @click="move(g.links,j,-1)" :disabled="!j">↑</button><button type="button" @click="move(g.links,j,1)" :disabled="j===g.links.length-1">↓</button><button type="button" @click="g.links.splice(j,1)">×</button></div><button type="button" @click="g.links.push({label:emptyText(),path:'/support',visible:true})" :disabled="g.links.length>=15">+ {{ $t('Add link') }}</button></article><button type="button" @click="form.groups.push({title:emptyText(),links:[]})" :disabled="form.groups.length>=6">+ {{ $t('Add group') }}</button></template>
<template v-else-if="scope==='support'"><p>Tawk</p><label><input type="checkbox" v-model="form.chat_enabled"> {{ $t('Enable online chat') }}</label><label>{{ $t('Chat URL') }}<input v-model.trim="form.chat_url" placeholder="https://tawk.to/chat/…/…"></label><label>{{ $t('Public support email') }}<input v-model.trim="form.email" type="email"></label><label>{{ $t('Service hours') }}<input v-model="form.hours[locale]" maxlength="200"></label><label>{{ $t('Service languages') }}<input v-model="form.languages" maxlength="100"></label><label>{{ $t('Chat availability') }}<themed-select v-model="form.availability"><option value="scheduled">{{ $t('According to service schedule') }}</option><option value="offline">{{ $t('Offline — use tickets') }}</option></themed-select></label><p>{{ $t('Service hours describe your staffing schedule, not live agent presence.') }}</p><div v-for="(channel,i) in form.order" :key="channel" class="link-row"><span>{{ $t(channelLabels[channel]) }}</span><button type="button" @click="move(form.order,i,-1)" :disabled="!i">↑</button><button type="button" @click="move(form.order,i,1)" :disabled="i===form.order.length-1">↓</button></div></template>
<template v-else><label>{{ $t('Trading rules introduction') }}<textarea v-model="form.rules_intro[locale]" maxlength="3000"></textarea></label><p>{{ $t('Fee and trading limit values are read from active business settings.') }}</p><article v-for="(item,i) in form.items" :key="i" class="editor-box"><div class="link-row"><input type="checkbox" v-model="item.visible" :aria-label="$t('Visible')"><themed-select v-model="item.category"><option v-for="k in ['account','assets','trading','umi']" :key="k" :value="k">{{ $t(categoryLabels[k]) }}</option></themed-select><button type="button" @click="move(form.items,i,-1)" :disabled="!i">↑</button><button type="button" @click="move(form.items,i,1)" :disabled="i===form.items.length-1">↓</button><button type="button" @click="form.items.splice(i,1)">{{ $t('Remove') }}</button></div><input v-model="item.question[locale]" :aria-label="$t('Question')" maxlength="200"><textarea v-model="item.answer[locale]" :aria-label="$t('Answer')" maxlength="3000"></textarea></article><button type="button" @click="form.items.push({question:emptyText(),answer:emptyText(),category:'account',visible:true})" :disabled="form.items.length>=60">+ {{ $t('Add FAQ') }}</button></template>
<details class="settings-preview"><summary>{{ $t('Preview current edits') }}</summary><template v-if="scope==='navigation'"><section v-for="(g,i) in form.groups" :key="i"><b>{{ text(g.title) }}</b><span v-for="(l,j) in g.links.filter(l=>l.visible&&(l.path!=='/docs/api'||form.api_public))" :key="j">{{ text(l.label) }} → {{ l.path }}</span></section></template><template v-else-if="scope==='support'"><h3>{{ $t('Deepro Support Center') }}</h3><p>{{ text(form.hours) }} {{ form.languages }}</p><p v-for="k in previewChannels" :key="k">{{ $t(channelLabels[k]) }} {{ k==='email'?form.email:'' }}</p></template><template v-else><p>{{ text(form.rules_intro) }}</p><article v-for="(q,i) in form.items.filter(q=>q.visible)" :key="i"><b>{{ text(q.question) }}</b><p>{{ text(q.answer) }}</p></article></template></details>
<label>{{ $t('Reason for change') }}<input v-model.trim="reason" maxlength="500"></label><div class="settings-toolbar"><button type="button" :disabled="saving||reason.length<5" @click="save('draft')">{{ $t('Save draft') }}</button><button type="button" class="publish" :disabled="saving||reason.length<5" @click="save('publish')">{{ $t('Publish') }}</button><button type="button" :disabled="saving" @click="load">{{ $t('Reload') }}</button></div>
<details><summary>{{ $t('Change history') }}</summary><article v-for="event in history" :key="event.id"><b>{{ event.created_at }} · #{{ event.actor_id }} · {{ event.action }}</b><p>{{ event.reason }}</p><pre>{{ JSON.stringify(event.changes,null,2) }}</pre></article></details></div><p role="status">{{ message }}</p></details></template>
<script>
import axios from 'axios';import {contentText} from '@/Functions/ContentText.mjs';
const clone=v=>JSON.parse(JSON.stringify(v));
export default{props:{scope:{type:String,required:true}},data:()=>({form:null,published:null,hasDraft:false,history:[],targets:[],revision:'',reason:'',locale:'zh-cn',saving:false,message:'',titles:{navigation:'Site content and navigation',support:'Support channel settings',help:'Help content and trading rules'},channelLabels:{chat:'Online Customer Service',tickets:'My tickets',email:'Email support',help:'Help Center'},categoryLabels:{account:'Account',assets:'Assets',trading:'Trade',umi:'UMI Ecosystem'}}),computed:{endpoint(){return this.route(this.scope==='support'?'admin.support-presentation':'admin.site-presentation',{scope:this.scope})},previewChannels(){return this.form.order.filter(k=>k!=='email'||this.form.email).filter(k=>k!=='chat'||this.form.chat_enabled&&this.form.availability!=='offline')}},methods:{text(v){return contentText(v,this.locale)},emptyText(){return {en:'','zh-cn':'','zh-tw':''}},move(rows,i,by){if(i+by<0||i+by>=rows.length)return;rows.splice(i+by,0,rows.splice(i,1)[0])},opened(e){if(e.target===this.$el&&e.target.open&&!this.form)this.load()},accept(data){this.published=data.published;this.form=clone(data.draft||data.published);this.hasDraft=!!data.draft;this.history=data.history;this.targets=data.targets;this.revision=data.revision},usePublished(){this.form=clone(this.published)},async load(){try{this.accept((await axios.get(this.endpoint)).data);this.message=''}catch(_){this.message=this.$t('Unable to load settings')}},async save(mode){this.saving=true;try{this.accept((await axios.put(this.endpoint,{settings:this.form,mode,revision:this.revision,reason:this.reason})).data);this.reason='';this.message=this.$t(mode==='publish'?'Published':'Draft saved')}catch(e){this.message=Object.values(e.response?.data?.errors||{}).flat().join(' ')||this.$t('Unable to save settings')}finally{this.saving=false}}}}
</script>
<style scoped>.site-operations{margin:20px 0;padding:20px;background:#fff;border:1px solid #dbe2ea;border-radius:12px;color:#27313b}.site-operations summary{font-weight:700;cursor:pointer}.site-operations label{display:block;margin:12px 0}.site-operations input:not([type=checkbox]),.site-operations select,.site-operations textarea{padding:8px;border:1px solid #cbd5e1;border-radius:6px;max-width:100%}.site-operations label>input:not([type=checkbox]),.site-operations textarea{display:block;width:100%}.site-operations textarea{min-height:90px}.site-operations p{margin:8px 0;color:#5c6875}.site-operations button{padding:7px 12px;border:1px solid #dbe2ea;border-radius:6px}.site-operations button:disabled{opacity:.4}.editor-box{padding:16px;background:#f8fafc;margin:16px 0;border-radius:8px}.settings-toolbar,.link-row,.moves{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin:8px 0}.link-row>span{min-width:150px}.publish{background:#f5d233}.settings-preview{padding:16px;background:#fffbe9;margin:20px 0}.settings-preview section{display:inline-flex;vertical-align:top;flex-direction:column;gap:8px;margin:12px}.settings-preview p{white-space:pre-wrap}.site-operations pre{max-height:320px;overflow:auto;font-size:12px}.site-operations article{margin:12px 0}</style>
